home_ar=[section('about','جذور عراقية.\nوطموح يتّسع.', 'من المقاولات والتجارة إلى التقنية والطاقة، تجمع ارض اليرموك مجالات عمل متنوعة ضمن رؤية تسعى إلى النمو والتطوير وخدمة السوق العراقي.',order=1),section('sectors','مجالات متنوّعة.\nرؤية واحدة.','اكتشف نطاق أعمالنا، واختر المجال الذي يلتقي مع احتياجات مشروعك.',order=2),section('approach','ما يجمع أعمالنا،\nهو ما نؤمن به.', 'مبادئ توجه العمل والعلاقات، كما يوضحها الملف التعريفي للشركة.',[{'title':'التخطيط والتطوير','text':'تخطيط فعّال وتطوير مستمر للكفاءات والتقنيات.'},{'title':'الجودة والالتزام','text':'العناية بالمواصفات والدقة في التنفيذ واحترام الجداول الزمنية.'},{'title':'علاقات طويلة الأمد','text':'الشفافية والمصداقية أساس التعامل مع الجهات الحكومية والخاصة.'}],3),section('profile','تعرّف علينا\nعن قرب.','رؤيتنا، قيمنا ومجالات عملنا في ملف واحد. تصفّح الملف التعريفي الرسمي لشركة ارض اليرموك.',order=4),section('cta','لنبدأ بمحادثة.','أخبرنا عن احتياجاتك، ودعنا نناقش كيف تتصل بمجالات عملنا.',order=5)]
home_en=[section('about','Iraqi roots.\nWider horizons.','From contracting and trade to technology and energy, ARD ALYARMWK CO. brings diverse activities together with a vision for growth, development and service to the Iraqi market.',order=1),section('sectors','Diverse sectors.\nOne vision.','Explore our activities and find the sector that connects with your project.',order=2),section('approach','Shared principles.\nAcross every field.','The principles that guide our work and relationships, as set out in our company profile.',[{'title':'Planning & development','text':'Effective planning and the continuous development of skills and technology.'},{'title':'Quality & commitment','text':'Attention to specifications, precise execution and respect for schedules.'},{'title':'Lasting relationships','text':'Transparency and credibility in our relationships with public and private organisations.'}],3),section('profile','A closer look\nat our company.','Our vision, values and fields of work in one place. Explore the official ARD ALYARMWK CO. profile.',order=4),section('cta','Every project starts\nwith a conversation.','Tell us what you need and let’s discuss how it connects with our fields of work.',order=5)]
items.append(item('pages','home',tr('نبني بثقة.\nونتقدّم برؤية.','ارض اليرموك، شركة عراقية تجمع المقاولات والتجارة والتقنية والطاقة، وتتطلع إلى المساهمة في تطوير الأعمال والبنى التحتية. ',{'eyebrow':'ارض اليرموك · آفاق متعددة','sections':home_ar},'PDF pp. 2, 6–9; editorial synthesis','ar'),tr('Built on trust.\nDriven by vision.','An Iraqi company bringing together contracting, trade, technology and energy, seeking to contribute to business and infrastructure development.',{'eyebrow':'ARD ALYARMWK CO. · WIDER HORIZONS','sections':home_en},'Proposed translation; PDF pp. 2, 6–9','en'),'architecture',0))
