items.append(item('pages','sectors',tr('تنوّع يصنع\nفرصاً أوسع.','ثمانية مجالات عمل تشمل البناء والتجارة والتقنية والخدمات والطاقة والصناعة، لتلبية احتياجات السوق العراقي.',{'eyebrow':'مجالات أعمالنا','sections':[]},'PDF physical pages 6–8','ar'),tr('More fields.\nMore possibilities.','Eight fields of work spanning construction, trade, technology, services, energy and industry to meet the needs of the Iraqi market.',{'eyebrow':'OUR SECTORS','sections':[]},'Proposed translation; PDF physical pages 6–8','en'),'energy',2))
items.append(item('pages','profile',tr('رؤيتنا وأعمالنا.\nبين يديك.','الملف التعريفي الرسمي لشركة ارض اليرموك؛ نبذة عن الشركة ورؤيتها ورسالتها وقيمها وأنشطتها وأهدافها الاستراتيجية.',{'eyebrow':'الملف التعريفي','sections':[section('contents','داخل الملف','',[{'title':'الشركة ورؤيتها','text':'التعريف بالشركة والرؤية والرسالة.'},{'title':'القيم والأهداف','text':'المبادئ والأهداف التي توجه أعمال الشركة.'},{'title':'مجالات العمل','text':'مجالات العمل وبيانات الاتصال الرسمية.'}])]},'User-supplied original 10-page PDF','ar'),tr('Our vision and work.\nIn your hands.','The official ARD ALYARMWK CO. profile: an introduction to the company, its vision, mission, values, activities and strategic objectives.',{'eyebrow':'COMPANY PROFILE','sections':[section('contents','Inside the profile','',[{'title':'Company & vision','text':'Company introduction, vision and mission.'},{'title':'Values & objectives','text':'The principles and objectives guiding our work.'},{'title':'Fields of work','text':'Business activities and official contact details.'}])]},'Proposed translation; original PDF is Arabic with English cover','en'),'profile-cover',3))
items.append(item('pages','contact',tr('لنتحدث عن\nمشروعك القادم.','شاركنا احتياجاتك أو استفسارك، وحدد القطاع المناسب ليتسنى لنا متابعة رسالتك.',{'eyebrow':'اتصل بنا','sections':[]},'Contact PDF physical page 10; form copy editorial','ar'),tr('Let’s talk about\nyour next project.','Share your requirements or enquiry and choose a relevant sector so we can follow up on your message.',{'eyebrow':'GET IN TOUCH','sections':[]},'Proposed translation; contact PDF physical page 10','en'),None,4))
privacy_ar=[section('collection','البيانات التي نجمعها','عند استخدام نموذج التواصل، نجمع الاسم والبريد الإلكتروني والرسالة. الشركة ورقم الهاتف والقطاع حقول اختيارية. تُحفظ لغة الرسالة وتاريخ إرسالها ورقمها المرجعي وحالة متابعتها.'),section('use','كيف نستخدم بياناتك','تستخدم الشركة بيانات التواصل للرد على الاستفسارات ومتابعة طلبات الأعمال. لا تُستخدم لإرسال حملات تسويقية من هذا الموقع. يُحفظ الطلب في قاعدة البيانات قبل تأكيد استلامه. عند تفعيل إشعارات البريد، يُرسل إلى البريد الإداري رقم الطلب ورابط لوحة الإدارة دون نص الرسالة.'),section('security','التخزين والحماية','الوصول إلى الرسائل محصور بالمسؤولين المخولين في لوحة الإدارة. يستخدم الموقع ملفات ارتباط ضرورية للجلسة وحماية النماذج؛ ولا يضيف أدوات تحليلات أو إعلانات. تُستخدم بصمة مشفرة لعنوان الاتصال لتحديد معدل الطلبات، وبصمة لمحتوى الرسالة لمنع التكرار؛ ولا يسجل التطبيق عنوان الاتصال الخام في قاعدة البيانات. قد تسجل خدمة الاستضافة بيانات وصول تقنية ضمن إعداداتها. يُحفظ اختيار النمط النهاري أو الليلي في متصفحك لتطبيقه عند عودتك، ولا يُرسل هذا الاختيار إلى الخادم. يمكنك تغيير الاختيار من زر النمط أو مسحه ضمن بيانات الموقع في متصفحك.'),section('rights','التواصل بشأن بياناتك','للاستفسار عن بياناتك أو طلب تصحيحها أو حذفها، راسل البريد الرسمي للشركة مع ذكر رقم الرسالة إن توفر. يمكن للمسؤول حذف الرسائل من لوحة الإدارة. تبقى الرسائل محفوظة إلى أن تُحذف، ولا توجد حالياً عملية حذف تلقائي.'),section('third','الملفات والروابط','تُحمّل الصور والخطوط والملف التعريفي من الموقع نفسه. لا تُحمّل خريطة أو خدمة خارجية تلقائياً. روابط الهاتف والبريد تفتح التطبيقات المناسبة على جهازك.')]
privacy_en=[section('collection','Information we collect','The contact form collects your name, email address and message. Company, phone number and sector are optional. We also store the message language, submission date, reference and follow-up status.'),section('use','How we use information','Contact information is used to respond to enquiries and follow up on business requests. This site does not use it for marketing campaigns. Requests are saved before receipt is confirmed. When email notifications are enabled, only the request reference and an admin link are emailed, without the message body.'),section('security','Storage and protection','Messages are accessible to authorised administrators. The site uses essential session and form-security cookies, with no analytics or advertising tools. A keyed hash of the connection address limits request frequency; a message fingerprint prevents duplicates. The application does not store the raw connection address in its database. The hosting service may keep technical access logs according to its configuration. Your light or dark mode preference is saved in your browser for future visits and is not sent to the server. You can change it using the theme button or remove it by clearing this site’s browser data.'),section('rights','Contact about your data','To ask about your data or request correction or deletion, contact the company’s official email and include your message reference if available. Administrators can delete messages. Messages remain stored until deleted, and no automatic deletion process currently runs.'),section('third','Files and external links','Images, fonts and the company profile are served by this site. No external map or service loads automatically. Phone and email links open the relevant apps on your device.')]
items.append(item('pages','privacy',tr('الخصوصية وبيانات التواصل','توضح هذه الصفحة البيانات التي يعالجها الموقع عند إرسال استفسار، وكيفية استخدامها وحمايتها.',{'eyebrow':'بياناتك','sections':privacy_ar},'Implemented functionality; retention policy pending','ar'),tr('Privacy & contact data','This page explains the information the site processes when you send an enquiry, how it is used and how it is protected.',{'eyebrow':'YOUR INFORMATION','sections':privacy_en},'Proposed translation; implemented functionality','en'),None,5))
